-- 3. Hapus duplikat ID lama jika ada (Kutai Kertanegara ID 430, Batanghari ID 69, Sitaro ID 509, Pangkep ID 513)
DELETE FROM kabupatens WHERE id IN (69, 430, 509, 513);

